import sqlite3
import os
import json
import numpy as np
import math
import pickle

if not os.path.exists("dictionaries"):
    os.makedirs("dictionaries")
punct_symbols = r'!"#$%&\'()*+,-./:;<=>?@[\\]^_`{|}~«»—…'

base = sqlite3.connect("example.db")
cursor = base.cursor()
cursor.execute("DROP TABLE IF EXISTS nodes")
cursor.execute("CREATE TABLE IF NOT EXISTS nodes (number INTEGER PRIMARY KEY AUTOINCREMENT , name TEXT, data TEXT, vector_id)")


# Список русских окончаний, отсортированный от самых длинных к коротким (generated by AI)
COMMON_ENDINGS = [
    # Прилагательные и местоимения (падежные окончания)
    "ого",
    "его",
    "ому",
    "ему",
    "ыми",
    "ими",
    "ых",
    "их",
    "ую",
    "юю",
    "ою",
    "ею",
    # Множественное число и падежи
    "ами",
    "ями",
    "ов",
    "ев",
    "ей",
    "ий",
    "ые",
    "ие",
    "ая",
    "яя",
    "ое",
    "ее",
    "ым",
    "им",
    "ах",
    "ях",
    # Простые окончания (существительные, глаголы)
    "а",
    "я",
    "о",
    "е",
    "ы",
    "и",
    "у",
    "ю",
    "ь",
    "й",
    "т",
    "ть",
    "л",
    "ла",
    "ло",
    "ли",
]
cnt = 0

word_to_id = dict()
id_to_word = dict()
count_unique_words = dict()
words_in_chunks = dict()
words_in_text = 0
chunks_avg = 0
def clear_ending(word):
    a = word.strip(punct_symbols).lower()
    for i in COMMON_ENDINGS:
        if a.endswith(i):
            return a[:-1*len(i)]
    return a
for i in os.listdir("data"):
    
    with open(os.path.join("data", i), "r", encoding='utf-8') as file:
        data = json.load(file)

        for name, line in data.items():
            chunks_avg += 1
            words_in_chunks[name] = set()
            tek_form = ''
            for word in line.split(" "):
                
                if not clear_ending(word):
                    continue
                if word[0] == "$" and word[-1] != "$":
                    tek_form = word
                elif tek_form:
                    tek_form += " " + word
                    if tek_form[-1] == "$":
                        tek_form = clear_ending(tek_form)

                        if tek_form in word_to_id:
                            words_in_text += 1
                            count_unique_words[tek_form] += 1
                        else:
                            count_unique_words[tek_form] = 1
                            word_to_id[tek_form] = cnt
                            id_to_word[cnt] = tek_form
                            cnt+=1
                            words_in_text += 1
                        words_in_chunks[name].add(word_to_id[tek_form])
                        tek_form = ''
                else:
                    word = clear_ending(word)
                    if word in word_to_id:
                        words_in_text += 1
                        count_unique_words[word] += 1
                    else:
                        words_in_text += 1
                        count_unique_words[word] = 1
                        word_to_id[word] = cnt
                        id_to_word[cnt] = word
                        cnt+=1
                    words_in_chunks[name].add(word_to_id[word])

    
                        
matrix = []
for i in os.listdir("data"):
    
    with open(os.path.join("data", i), "r", encoding='utf-8') as file:
        data = json.load(file)
        cnt = 0

        for name, line in data.items():

            vector = np.zeros(len(word_to_id))
            tek_form = ''
            for word in line.split(" "):
                
                if not clear_ending(word):
                    continue
                if word[0] == "$" and word[-1] != "$":
                    tek_form = word
                elif tek_form:
                    tek_form += " " + word
                    if tek_form[-1] == "$":
                        tek_form = clear_ending(tek_form)
                        count = 0
                        for s in words_in_chunks.values():
                   
                            if word_to_id[tek_form] in s:
                                count+=1
                        #print(count)
                        vector[word_to_id[tek_form]] = (count_unique_words[tek_form] / words_in_text) * math.log(chunks_avg / count)


                        tek_form = ''

                        
                else:
                    word = clear_ending(word)
                   

                    count = 0
                    for s in words_in_chunks.values():
                   
                        if word_to_id[word] in s:
                            count+=1
                    #print(count)
                    vector[word_to_id[word]] = (count_unique_words[word] / words_in_text) * math.log(chunks_avg / count)
                    #print(np.sum(vector))
            a = np.linalg.norm(vector)
            if a != 0:
                vector/= a
            
            cursor.execute("INSERT INTO nodes (name, data, vector_id) VALUES (?,?,?)", (name, line, len(matrix)))
            matrix.append(vector)
            #print(np.sum(vector))
            #print(sum(matrix[-1]))
       
matrix = np.array(matrix)

np.save("matrix.npy", matrix)




with open(os.path.join("dictionaries", "word_to_id"), "wb") as f:
    pickle.dump(word_to_id, f)
with open(os.path.join("dictionaries", "id_to_word"), "wb") as f:
    pickle.dump(id_to_word, f)
with open(os.path.join("dictionaries", "count_unique_words"), "wb") as f:
    pickle.dump(count_unique_words, f)
with open(os.path.join("dictionaries", "words_in_chunks"), "wb") as f:
    pickle.dump(words_in_chunks, f)  
string = f"{words_in_text} \n {chunks_avg}"
with open(os.path.join("dictionaries", "data_for_words"), "w", encoding="utf-8") as f:
    f.write(string)
base.commit()
cursor.close()
